  jered: { n: "Jered", v: "mahalaleel", boek: ["genesis"], kort: "Zoon van Mahalaleël en vader van Henoch.",
    geb: "Genesis 5:15", dood: "Genesis 5:20", leeftijd: [[162, "Genesis 5:18"], [962, "Genesis 5:20"]] },
